-- Publishes the map preview and preserves verified travel prefixes during planning.

local Constants = APR.NavigationConstants.Navigation

local nav = APR.navigation
local Shared = APR.navigation._helpers
local DepartureAllowed = Shared.DepartureAllowed
local Distance = Shared.Distance
local HasWalkingPath = Shared.HasWalkingPath
local MissingWalkProof = Shared.MissingWalkProof
local PlanningRequestCurrent = Shared.PlanningRequestCurrent
local Position = Shared.Position
local ReuseWalkingCursor = Shared.ReuseWalkingCursor
local WalkingProvider = Shared.WalkingProvider

function nav:UpdateWalkingPreview(fragments, job)
    if not fragments or self.walkingPreview == fragments or (self:IsNavigating() and not self.walkingPrefix) then
        return
    end
    local generation, context, inputs = self.generation, self.context, self._routeInputs
    local first, current = fragments[1], self.walkingPrefix
    local published
    if first and not first.breakBefore then
        local path = first.path
        local row = self:PrepareGuidanceStep(
            { kind = "walk", from = path[1], to = path[#path], path = path },
            "preview",
            generation,
            self.start
        )
        if first.departure or (job and fragments == job.entryWalkPreview) then row.arrivalRadius = 2 end
        ReuseWalkingCursor(row, current)
        local _, reachable = self:AdvanceWalkingPath(row, Position(), nil, true)
        if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        if reachable then
            self.walkingPrefix, self.queue, self.cursor, self.state = row, { row }, 1, "guiding"
            self.retainedArrow = nil
            published = true
        end
    end
    self.walkingPreview = fragments
    self:Notify()
    if
        published
        and job
        and job.startedAt
        and not job.firstGuidanceMilliseconds
        and debugprofilestop
        and PlanningRequestCurrent(self, context, generation, job, inputs)
    then
        job.firstGuidanceMilliseconds = debugprofilestop() - job.startedAt
        if APR.RecordPerformanceDuration then
            APR:RecordPerformanceDuration("NavigationFirstValidatedGuidance", job.firstGuidanceMilliseconds)
        end
    end
end--[[APR_DIAG]]; nav.UpdateWalkingPreview = APRTrace("APR-Core/features/navigation/controller/NavigationPreview.lua:21:nav:UpdateWalkingPreview#1", nav.UpdateWalkingPreview)--[[/APR_DIAG]]

function nav:PublishTravelPrefix(segments, job)
    if not segments or self.travelPrefix or (self:IsNavigating() and not self.walkingPrefix) then return end
    local generation, context, inputs = self.generation, self.context, self._routeInputs
    local position, queue = Position(), {}
    if not position then return end
    for index, segment in ipairs(segments) do
        local row = self:PrepareGuidanceStep(segment, index, generation, position)
        if not row or MissingWalkProof(row, WalkingProvider()) then return end
        queue[index] = row
    end
    local transport = queue[#queue]
    if
        not transport
        or (not HasWalkingPath(queue[1]) and Distance(position, transport.from) > 20)
        or DepartureAllowed(transport, transport.from) ~= true
    then
        return
    end
    ReuseWalkingCursor(queue[1], self.walkingPrefix)
    local _, reachable = self:AdvanceWalkingPath(queue[1], position, nil, true)
    if not reachable or not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    self.walkingPrefix, self.walkingPreview, self.retainedArrow = nil, nil, nil
    self.travelPrefix, self.queue, self.cursor, self.state = transport, queue, 1, "guiding"
    if job.waypointLeg and job.waypointLeg.transport then
        job.waypointLeg.before = queue
        self.waypointPendingLeg = job.waypointLeg
        self.waypointJourney = true
    end
    self:Notify()
end--[[APR_DIAG]]; nav.PublishTravelPrefix = APRTrace("APR-Core/features/navigation/controller/NavigationPreview.lua:63:nav:PublishTravelPrefix#2", nav.PublishTravelPrefix)--[[/APR_DIAG]]

function nav:GetPreview()
    local service = APR.Services and APR.Services:GetStep()
    local servicePin = service and (service._mapWaypoint or service.serviceWaypoint)
    local guiding = self:IsNavigating()
    local fragments = (not guiding or self.walkingPrefix) and self.walkingPreview
    if self:BlocksDirectGuidance() and not fragments and not servicePin then return Constants.EMPTY_GUIDANCE end
    local guidance = guiding and self.queue
        or fragments
        or self.waypointPendingLeg and self.waypointPendingLeg.after
        or Constants.EMPTY_GUIDANCE
    if guiding and self.walkingPrefix and fragments and fragments[#fragments].breakBefore then
        guidance = { self.walkingPrefix, fragments.estimate or fragments[#fragments] }
        if fragments.estimate then guidance[3] = fragments[#fragments] end
    elseif not guiding and fragments and fragments.estimate then
        guidance = { fragments[1], fragments.estimate, fragments[2] }
    end
    local cursor = guiding and self.cursor or 1
    if
        self.waypointPreview or (not guiding and self.waypointPendingLeg and guidance == self.waypointPendingLeg.after)
    then
        local points = {}
        for index = cursor, #guidance do
            points[#points + 1] = guidance[index]
        end
        if not guiding and points[1] then
            local detached = { breakBefore = true }
            for key, value in pairs(points[1]) do
                detached[key] = value
            end
            points[1] = detached
        end
        for _, fragment in ipairs(self.waypointPreview or Constants.EMPTY_GUIDANCE) do
            points[#points + 1] = fragment
        end
        guidance, cursor = points, 1
    end
    local provider = guiding and WalkingProvider()
    if provider and provider.RequiresWalkingProof then
        for i = cursor, #guidance do
            if MissingWalkProof(guidance[i], provider) then
                if not servicePin then return Constants.EMPTY_GUIDANCE end
                guidance, cursor = Constants.EMPTY_GUIDANCE, 1
                break
            end
        end
    end
    local step, index, steps
    if service then
        step, index, steps = service, 1, { service }
    else
        step, index, steps = APR:GetCurrentStep()
    end
    local unlockPreview = not service and APR.GetNavigationUnlockStep and APR:GetNavigationUnlockStep()
    if unlockPreview then
        step, index, steps = unlockPreview, 1, { unlockPreview }
    end
    if APR.navigationPreview then return APR.navigationPreview:Build(guidance, step, index, steps, cursor) end
    local remaining = {}
    for i = cursor, #guidance do
        remaining[#remaining + 1] = guidance[i]
    end
    return remaining
end--[[APR_DIAG]]; nav.GetPreview = APRTrace("APR-Core/features/navigation/controller/NavigationPreview.lua:94:nav:GetPreview#3", nav.GetPreview)--[[/APR_DIAG]]

function nav:ClearNavigationUiLines()
    local ui = APR.currentStep
    if not ui then return end
    local function navigationKey(key)
        return (APR.IsNavigationQuestUiKey and APR:IsNavigationQuestUiKey(key))
            or (APR.IsNavigationExtraTextUiKey and APR:IsNavigationExtraTextUiKey(key))
            or key == self.NavigationStepKey
            or key == self.ErrorStepKey
            or key == self.ErrorDestinationLineKey
            or key == self.NavigationDividerStepKey
            or (type(key) == "string" and (key:match("^01_NAVIGATION_PATH%-") or key:match("^01_NAVIGATION_ERROR%-")))
    end--[[APR_DIAG]]; navigationKey = APRTrace("APR-Core/features/navigation/controller/NavigationPreview.lua:161:navigationKey#5", navigationKey)--[[/APR_DIAG]]
    -- A combat-deferred secure request can outlive its row. Its generation is
    -- encoded in the key, so discard every retired navigation request directly.
    for _, pending in ipairs({
        ui.pendingButtonRequests or {},
        ui.pendingButtonResets or {},
        ui.pendingRaidIconRequests or {},
    }) do
        for key in pairs(pending) do
            if navigationKey(key) then pending[key] = nil end
        end
    end
    if not ui.pendingRemoval then
        self._renderedState, self._renderedStep = nil, nil
        return
    end
    local inCombat = InCombatLockdown and InCombatLockdown()
    for _, list in ipairs({ ui.questsList or {}, ui.questsExtraTextList or {} }) do
        for key, container in pairs(list) do
            if navigationKey(key) then
                if inCombat then
                    ui:SoftHide(container)
                    ui.pendingContainerDestroy[#ui.pendingContainerDestroy + 1] = container
                    if ui.pendingButtonRequests then ui.pendingButtonRequests[key] = nil end
                    list[key] = nil
                else
                    ui.pendingRemoval[key] = true
                end
            end
        end
    end
    if not inCombat and next(ui.pendingRemoval) then ui:FlushPendingContainers() end
    self._renderedState, self._renderedStep = nil, nil
end--[[APR_DIAG]]; nav.ClearNavigationUiLines = APRTrace("APR-Core/features/navigation/controller/NavigationPreview.lua:158:nav:ClearNavigationUiLines#4", nav.ClearNavigationUiLines)--[[/APR_DIAG]]
